#[derive(Clone, Default)]
pub struct MemoryProductRepository {
    rows: Arc<Mutex<Vec<Product>>>,
    next_id: Arc<Mutex<i64>>,
}

impl MemoryProductRepository {
    /// The rows reads see, by primary key.
    fn visible(&self) -> Vec<Product> {
        let mut rows: Vec<Product> = self.rows.lock().unwrap().iter().filter(|row| row.deleted_at.is_none()).cloned().collect();
        rows.sort_by(|a, b| key_of(a).partial_cmp(&key_of(b)).unwrap_or(Ordering::Equal));
        rows
    }

    /// Keeps a row, in place of the one with its key.
    fn store(&self, entity: &Product) {
