    }

    async fn find_all_by_status(&self, status: String) -> Result<Vec<Product>, DomainError> {
        Ok(self.visible().into_iter().filter(|row| row.status.as_ref() == Some(&status)).collect())
    }

    async fn insert(&self, entity: Product) -> Result<Product, DomainError> {
        let mut entity = entity;
        entity.id = entity.id.or_else(|| {
            let mut next = self.next_id.lock().unwrap();
            *next += 1;
            Some(*next)
        });
        entity.version = entity.version.or_else(|| Some(1));
        self.store(&entity);
        Ok(entity)
    }

    async fn update(&self, entity: Product) -> Result<Product, DomainError> {
        self.store(&entity);
        Ok(entity)
    }

    async fn delete(&self, entity: &Product) -> Result<(), DomainError> {
        self.rows.lock().unwrap().retain(|row| key_of(row) != key_of(entity));
        Ok(())
    }
}

