/// The values an update gives, by field.
fn given(changes: ProductUpdate) -> Values {
    Values { category_id: changes.category_id.given(), name: changes.name.given(), price: changes.price.given(), status: changes.status.given(), version: changes.version.given(), deleted_at: changes.deleted_at.given() }
}

