//! The test database: the PostgreSQL database TEST_DATABASE_URL names, created from the SeaORM entities before every test.

use sea_orm::{ConnectionTrait, Database, DatabaseConnection, Schema, Statement};
use seaorm_postgresql_dtos_patch::entities::{audit_log_table as audit_log_table, category_table as categories_table, customer_table as customers_table, order_line_table as order_lines_table, order_table as orders_table, product_table as products_table, product_tag_table as product_tags_table, tag_table as tags_table};
use seaorm_postgresql_dtos_patch::unit_of_work::SqlUnitOfWork;
use tokio::sync::{Mutex, MutexGuard};

/// Every test empties the same database: they take turns
static TURN: Mutex<()> = Mutex::const_new(());

/// A connection to the test database.
async fn connect() -> DatabaseConnection {
    // The entities are written for one kind of database: the tests cannot fall back to SQLite
    let url = std::env::var("TEST_DATABASE_URL").expect("The database tests need a disposable PostgreSQL database: set TEST_DATABASE_URL (it is emptied)");
    Database::connect(&url).await.expect("the test database")
}

/// The repositories over the test database, with every table dropped and created again, and the turn of the test
/// that holds it.
pub async fn open() -> (MutexGuard<'static, ()>, SqlUnitOfWork) {
    let turn = TURN.lock().await;
    let db = connect().await;
    db.execute_unprepared("DROP TABLE IF EXISTS \"audit_log\" CASCADE").await.expect("DROP TABLE IF EXISTS \"audit_log\" CASCADE");
    db.execute_unprepared("DROP TABLE IF EXISTS \"product_tags\" CASCADE").await.expect("DROP TABLE IF EXISTS \"product_tags\" CASCADE");
    db.execute_unprepared("DROP TABLE IF EXISTS \"tags\" CASCADE").await.expect("DROP TABLE IF EXISTS \"tags\" CASCADE");
    db.execute_unprepared("DROP TABLE IF EXISTS \"order_lines\" CASCADE").await.expect("DROP TABLE IF EXISTS \"order_lines\" CASCADE");
    db.execute_unprepared("DROP TABLE IF EXISTS \"orders\" CASCADE").await.expect("DROP TABLE IF EXISTS \"orders\" CASCADE");
    db.execute_unprepared("DROP TABLE IF EXISTS \"products\" CASCADE").await.expect("DROP TABLE IF EXISTS \"products\" CASCADE");
    db.execute_unprepared("DROP TABLE IF EXISTS \"categories\" CASCADE").await.expect("DROP TABLE IF EXISTS \"categories\" CASCADE");
    db.execute_unprepared("DROP TABLE IF EXISTS \"customers\" CASCADE").await.expect("DROP TABLE IF EXISTS \"customers\" CASCADE");
    Schema::new(db.get_database_backend())
        .builder()
        .register(customers_table::Entity)
        .register(categories_table::Entity)
        .register(products_table::Entity)
        .register(orders_table::Entity)
        .register(order_lines_table::Entity)
        .register(tags_table::Entity)
        .register(product_tags_table::Entity)
        .register(audit_log_table::Entity)
        .apply(&db)
        .await
        .expect("the tables");
    (turn, SqlUnitOfWork::new(db))
}

#[tokio::test]
async fn is_the_one_test_database_url_names() {
    let _turn = TURN.lock().await;
    let db = connect().await;
    let row = db.query_one_raw(Statement::from_string(db.get_database_backend(), "SELECT current_database()")).await.expect("a query").expect("a row");
    let value: String = row.try_get_by_index(0).expect("a value");
    let url = std::env::var("TEST_DATABASE_URL").expect("TEST_DATABASE_URL");
    assert_eq!(url.rsplit('/').next().and_then(|name| name.split('?').next()), Some(value.as_str()));
}

